    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Upis i brisanje n-torki odnosa — tko posjeduje, uređuje ili pregledava koje resurse vaše aplikacije. Upis odmah dodjeljuje ili opoziva pristup u aplikaciji.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Zamjena autorizacijske sheme — vrsta resursa i načina određivanja svakog odnosa. Odmah mijenja odgovor na svaku provjeru u ovom okruženju.',
    'read_the_authentication_policy_the_social_login_provide_758352e3' => 'Čitanje pravila autentifikacije, pružatelja prijave putem društvenih računa i izjave o naslijeđenoj prijavi — nikada tajnog ključa pružatelja.',
    'change_password_mfa_and_sso_rules_self_service_sign_up_66c7cb03' => 'Promjena pravila za lozinke, MFA i SSO, samostalne registracije, pružatelja prijave putem društvenih računa i odobrenja naslijeđene prijave.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Pregled načina rada Radara, ugrađenih i prilagođenih pravila, popisa dopuštenih i blokiranih te preglednika odluka — zašto su prijava ili registracija dopuštene, podvrgnute dodatnoj provjeri ili blokirane. Nikada IP adresa ni druga adresa iz odluke.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Stvaranje, promjena redoslijeda i brisanje pravila Radara, podešavanje ugrađenih pravila te dodavanje ili uklanjanje stavki s popisa dopuštenih i blokiranih.',
    'switch_radar_between_monitor_record_only_and_enforce_bl_c3ec2073' => 'Prebacivanje Radara između nadzora (samo bilježenje) i provedbe (blokiranje i dodatne provjere) — uključivanje ili isključivanje zaštite prijave u okruženju.',
    'list_the_publishable_keys_browser_apps_present_to_the_f_9a4fe3ce' => 'Prikaz javno dostupnih ključeva koje aplikacije u pregledniku šalju Frontend API-ju te njihovih dopuštenih izvora.',
    'create_publishable_keys_change_which_origins_may_presen_79684ec2' => 'Stvaranje javno dostupnih ključeva, promjena izvora koji ih smiju slati i opoziv ključeva.',
    'list_the_applications_that_trust_this_environment_as_th_61538b0b' => 'Prikaz aplikacija koje ovom okruženju vjeruju kao SAML pružatelju identiteta — nikada njihovih certifikata.',
    'register_change_and_remove_the_applications_people_sign_6b6a4041' => 'Registracija, promjena i uklanjanje aplikacija u koje se korisnici prijavljuju svojim ovdašnjim računom.',
    'read_the_hosted_sign_in_theme_and_branding_of_the_envir_c85a3622' => 'Pregled teme i vizualnog identiteta hostane prijave okruženja i njegovih organizacija.',
    'change_the_hosted_sign_in_theme_and_branding_of_the_env_bc832c7e' => 'Promjena teme i vizualnog identiteta hostane prijave okruženja i njegovih organizacija.',
    'read_this_environment_s_custom_domain_and_the_dns_recor_4408e8a7' => 'Pregled prilagođene domene ovog okruženja i DNS zapisa koji je potvrđuje.',
    'add_verify_and_remove_the_custom_domain_this_environmen_9a4835eb' => 'Dodavanje, provjera i uklanjanje prilagođene domene na kojoj je dostupno ovo okruženje.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Trajno brisanje osobe (čl. 17. GDPR-a): brišu se njezine vjerodajnice, sesije, članstva i osobni podaci, a račun se pseudonimizira. Radnja se ne može poništiti.',
    'create_rename_re_permission_and_delete_roles_and_author_dca95601' => 'Stvaranje, preimenovanje, promjena ovlasti i brisanje uloga te definiranje ručnih dopuštenja od kojih se sastoje. Dodjeljivanje uloga osobama zahtijeva `roles:write`.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Prikaz SAML i OIDC veza putem kojih se organizacije prijavljuju te domena e-pošte koje usmjeravaju korisnike na njih — nikada certifikata, tajnih ključeva klijenta ni ključeva za potpisivanje.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Stvaranje, promjena, omogućivanje, onemogućivanje i brisanje SSO veza, zahtijevanje SSO-a za organizaciju te provjera njezinih domena e-pošte i obvezno usmjeravanje na SSO. Mijenja način prijave korisnika.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Prikaz direktorija (SCIM, Google Workspace, Microsoft Entra) iz kojih se sinkroniziraju korisnici, njihovih grupa i pogrešaka sinkronizacije — nikada bearer tokena ni vjerodajnica pružatelja.',
    'connect_rename_pause_re_key_and_delete_inbound_director_9cb4cce4' => 'Povezivanje, preimenovanje, pauziranje, zamjena ključeva i brisanje izvornih direktorija te povezivanje njihovih grupa s ulogama. Novi ili zamijenjeni SCIM bearer token prikazuje se samo jednom.',
    'list_the_downstream_scim_targets_this_environment_pushe_2753c203' => 'Prikaz odredišnih SCIM sustava u koje ovo okruženje šalje korisnike i eventualnih pogrešaka — nikada njihovih vjerodajnica.',
    'register_pause_resume_and_delete_the_scim_targets_this_ca3c3bb1' => 'Registracija, pauziranje, nastavak i brisanje SCIM odredišta u koja ovo okruženje šalje podatke korisnika.',
    'read_role_conflict_segregation_of_duties_rules_and_acce_8572d9a3' => 'Čitanje pravila sukoba uloga (razdvajanja dužnosti) i pregleda pristupa, sa svim stavkama za koje se traži potvrda.',
    'define_switch_and_remove_role_conflict_rules_open_acces_34e40e6c' => 'Definiranje, uključivanje, isključivanje i uklanjanje pravila sukoba uloga; otvaranje pregleda pristupa, bilježenje odluka i zatvaranje pregleda — zatvaranje primjenjuje sve opozive.',
    'list_the_downstream_credentials_stored_in_the_token_vau_15a080ce' => 'Prikaz vjerodajnica za vanjske sustave pohranjenih u trezoru tokena i aplikacija koje mogu dobiti privremeni pristup svakoj — nikada pohranjenih vrijednosti.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Pohrana, rotacija i opoziv vjerodajnica za vanjske sustave te dodjeljivanje ili oduzimanje prava aplikaciji na privremeni pristup. To nisu opsezi vault.manage / vault.lease u tokenu same aplikacije.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Prikaz zastavica funkcionalnosti i njihova ciljanja te vrednovanje svake zastavice za korisnika u organizaciji — ono što pozadinski sustav aplikacije traži kada nema token.',
    'define_switch_retarget_and_delete_feature_flags_which_f_e64692af' => 'Definiranje, uključivanje, isključivanje, promjena ciljanja i brisanje zastavica funkcionalnosti — koje funkcionalnosti dobivaju koji korisnici i organizacije.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Prikaz vanjskih pružatelja s kojima korisnici mogu povezati račune, aplikacija koje mogu dobiti privremeni pristup tim tokenima i povezanih korisnika — nikada tajnih ključeva klijenta ni tokena.',
    'configure_change_and_remove_pipes_grant_or_withdraw_an_f69a04e9' => 'Konfiguriranje, promjena i uklanjanje integracija pipes, dodjeljivanje ili oduzimanje prava aplikaciji na privremeni pristup tokenima povezanih računa te odspajanje korisničkog računa.',
    'list_an_organization_s_recent_admin_portal_links_what_e_f1c55153' => 'Prikaz nedavnih poveznica organizacije na Administratorski portal: što svaka otvara, tko ju je stvorio, kome je poslana e-poštom i njezina statusa — nikada same poveznice.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Stvaranje i povlačenje jednokratne poveznice na Administratorski portal koja IT administratoru organizacije omogućuje postavljanje SSO-a, domena ili sinkronizacije direktorija bez računa. Nova poveznica prikazuje se samo jednom.',
    'list_the_pending_requests_from_agents_to_act_as_one_of_67e57ec8' => 'Prikaz zahtjeva agenata na čekanju za djelovanje u ime osobe iz ovog okruženja (OIDC CIBA): koja aplikacija, za koga i što traži.',
