    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Uloga je oznaka zapisana u token — uloge koje deklarira aplikacija ovdje su samo za čitanje, a ostale definirate vi. :part2 :part3 :part4 — svaki član ima i točno jednu takvu ulogu (Vlasnik, Administrator, Razvojni programer, Član ili Pregledavatelj), koja određuje što smije administrirati u ovoj konzoli.',
