    'catalog_edit_named' => 'Uredi :name',
    'https_or_http_on_localhost_leave_empty_and_t_6d61df22' => 'HTTPS ili HTTP na localhostu. Ostavite prazno i aplikacija neće biti obaviještena.',
    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Zastavica značajke je prekidač čije stanje aplikacije provjeravaju za pojedinu osobu u organizaciji. Uključite je za odabrane korisnike, organizacije ili postotak svih korisnika. Svaka aplikacija dobiva isti odgovor, u tvrdnji `feature_flags` tokena ili s krajnje točke za procjenu, bez nove implementacije. Pravilo korisnika ima prednost pred pravilom organizacije, ono pred postupnim uključivanjem, a ono pred zadanom vrijednošću.',
    'every_sign_in_and_sign_up_in_this_environment_is_judged_083be88e' => 'Svaka prijava i registracija u ovom okruženju ovdje se procjenjuje i bilježi od prvog pokušaja.',
    'everyone_currently_assigned_this_role_loses_the_access_5141955e' => 'Svi kojima je ova uloga trenutačno dodijeljena gube pristup koji pruža. Ova se radnja ne može poništiti.',
    'everyone_currently_assigned_this_role_loses_the_access_f7fa28ec' => 'Svi kojima je ova uloga trenutačno dodijeljena gube pristup koji pruža.',
