    'it_is_called_again_at_the_hook_point_from_the_next_matc_a4d12b55' => 'Ponovno se poziva na točki hooka od sljedeće odgovarajuće operacije.',
    'it_stops_being_able_to_act_as_you_immediately_and_has_t_5c3d584b' => 'Odmah gubi mogućnost djelovanja u vaše ime i mora ponovno zatražiti vaše odobrenje.',
    'it_stops_being_called_at_the_hook_point_the_operation_i_72937229' => 'Prestaje se pozivati na točki hooka. Operacija na koju je odgovarao nastavlja se bez njega.',
    'it_stops_working_immediately_anything_still_using_it_fa_4a9caff7' => 'Odmah prestaje raditi. Sve što ga još koristi neće se moći prijaviti.',
    'it_uses_pkce_and_gets_no_secret_nothing_to_l_f9fee647' => 'Koristi PKCE i ne dobiva tajnu — nema što procuriti iz preglednika ili telefona.',
    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'Njegovi se događaji odsad prihvaćaju bez provjere — ili odbijaju ako je uključen strogi način rada.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Njegovi se članovi mogu ponovno prijavljivati, a okruženja nastavljaju pružati autentifikaciju.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Vlastite vjerodajnice umjesto vjerodajnica okruženja za ovog pružatelja.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Ključ je izrađen. Zalijepite ga u frontend — namijenjen je javnoj upotrebi.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Ključ je zamijenjen — sada kopirajte novi. Stari ključ nastavlja raditi još 24 sata.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Na stranici za prijavu prikazuje gumbe za Google, GitHub, Apple i druge pružatelje za korisnike koji radije koriste postojeći račun nego stvaraju novu lozinku. Pružatelja postavite jednom za okruženje i bit će dostupan svim organizacijama. Organizacija može koristiti vlastite pristupne podatke ili isključiti pružatelja. Unosite pristupne podatke, a ostalo se popunjava automatski. Sama adresa koju pružatelj pošalje nikada nije dovoljna za pristup postojećem računu ovdje.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Ključevi kojima se vaš kod predstavlja Cbox ID-u, s karticom za svaku vrstu. Tajni ključ, odnosno upravljački ključ, omogućuje backendu upravljanje organizacijama, članovima, pozivnicama, ulogama i aplikacijama jednog okruženja. Ključ organizacije poziva njezin API s ugrađenom ulogom. Javni ključ koristi se u aplikaciji u pregledniku i radi samo s dopuštenih izvora. Tajni ključevi i ključevi organizacije prikazuju se samo jednom. Kopirajte ih pri stvaranju i odmah ih opozovite ako procure.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Registrira aplikacije koje prihvaćaju ovo okruženje kao SAML pružatelja identiteta, pa se korisnici prijavljuju postojećim računima koje ovdje imaju. Svakoj aplikaciji dodijelite njezinu organizaciju kako bi pristup imali samo članovi te organizacije. Bez dodijeljene organizacije aplikacija je dostupna svim korisnicima okruženja. To je izlazni smjer. Za prijavu poslovnim računom iz drugog sustava koristite Jedinstvenu prijavu za tvrtke u odjeljku Autentifikacija.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Odaberite framework u kojem razvijate. Stvara se aplikacija s preusmjeravanjem na lokalni razvojni poslužitelj, blokom konfiguracije okruženja za lijepljenje i kodom za prijavu korisnika. Stranica čeka stvarnu prijavu. Ispod su koraci pripreme proizvoda: vizualni identitet, organizacije, jedinstvena prijava, agent, suradnik i produkcija. Dovršenost se označava prema stvarnom stanju okruženja, nikada ručno.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar procjenjuje svaku prijavu i registraciju: pokušaje s ukradenim pristupnim podacima, brzinu tipičnu za botove, nemoguća putovanja, nove uređaje, anonimizacijske mreže i jednokratne adrese, uz vaša pravila te popise dopuštenih i blokiranih vrijednosti. Bilježi svaku odluku i, nakon uključivanja provedbe pravila, blokira pristup ili traži drugi faktor. Ovdje pregledajte odluke prije uključivanja provedbe i kada se netko ne može prijaviti.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Prekidači značajki koje aplikacije provjeravaju za određenu osobu u organizaciji. Uključite značajku za odabrane korisnike, organizacije ili dio svih korisnika. Svaka aplikacija čita isti odgovor iz tokena ili API-ja.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Softver koji djeluje u ovom okruženju pomoću ključa za upravljanje: Claude Code, Cursor, interni bot ili vaš backend. Svaki ima samo opsege pristupa koje ste mu dodijelili i čeka vaše odobrenje ondje gdje ste ga zatražili.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Primatelj zadržava istu tajnu. Tajna od 64 heksadecimalna znaka postaje whsec_ iza kojeg slijedi base64 kodiranje tog heksadecimalnog niza — "whsec_" + base64(secret). Tajna koja već počinje s whsec_ koristi se bez promjena.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Organizacije, korisnici i aktivne sesije iz svih okruženja ove instalacije te organizacije s najviše članova. Ovaj prikaz samo čita podatke i nikada ne mijenja okruženje odabrano u konzoli.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Svi koji se mogu prijaviti u ovu organizaciju i poslane pozivnice koje još nitko nije prihvatio. Pozovite ljude e-poštom; sami postavljaju prijavu, pa nikad ne morate rukovati tuđom lozinkom.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Omogućite prijavu postojećim računom. Postavite pružatelja jednom za okruženje i bit će dostupan u svim organizacijama. Organizacija može koristiti vlastite vjerodajnice ili isključiti pružatelja.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar procjenjuje svaku prijavu i registraciju: pokušaje s ukradenim vjerodajnicama, brzinu tipičnu za botove, nemoguća putovanja, nove uređaje, mreže za anonimizaciju, privremene adrese te vaša pravila i popise. Bilježi i razlog odluke.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Ovaj korisnik više se ne može prijaviti ni u jednu aplikaciju u ovom okruženju, a njegove postojeće sesije prestaju raditi pri sljedećem zahtjevu. Njegovi podaci ostaju sačuvani i možete ga ponovno aktivirati u bilo kojem trenutku.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Procjena se provodi redom: popis blokiranih, popis dopuštenih, vaša pravila od vrha prema dolje (odlučuje prvo koje odgovara), zatim ugrađena pravila (odlučuje najstrože od aktiviranih). Ako nema podudaranja, pristup se dopušta.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Većina integracija treba webhooks: oni se izvršavaju nakon događaja i ne mogu ga zadržati. Upotrijebite hook samo kada vaš sustav mora sudjelovati u odlučivanju tijekom prijave ili izdavanja tokena.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Ovdje se prikazuju ključevi koje izradite i vrijeme njihove posljednje upotrebe.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Ostavite prazno za rad bez zaključavanja — zadano zaključavanje u ovoj instalaciji je isključeno.',
    'let_people_sign_in_with_the_company_account_they_alread_b98aff03' => 'Omogućite korisnicima prijavu postojećim računom tvrtke umjesto zasebnom lozinkom ovdje.',
    'log_stream_saved_delivery_is_tried_again_on_the_next_ru_fb2e3c84' => 'Tok dnevnika je spremljen. Isporuka će se ponovno pokušati pri sljedećem pokretanju.',
    'management_key_created_copy_it_now_it_will_not_be_shown_9ec713ad' => 'Upravljački ključ je izrađen — sada ga kopirajte, više se neće prikazati.',
    'map_a_group_onto_the_roles_everyone_in_it_should_hold_m_1a407a38' => 'Povežite grupu s ulogama koje svi njezini članovi trebaju imati. Članstvo se sinkronizira, a uloge ga prate.',
