    'these_apply_to_every_organization_in_part1_not_only_par_ac56590d' => 'Ovo vrijedi za sve organizacije u :part1, ne samo za :part2.',
    'these_are_its_own_credentials_for_that_environment_s_co_a68e7d01' => 'To su vlastite vjerodajnice aplikacije za konfiguraciju tog okruženja. :part1',
    'they_become_the_owner_of_part1_and_you_become_an_admin_09c4a8dc' => 'Ta osoba postaje vlasnik :part1, a vi administrator. Samo vam novi vlasnik može vratiti vlasništvo.',
