    'they_get_an_email_with_a_link_nothing_changes_until_the_e94c64b9' => 'Dobit će e-poruku s poveznicom. Ništa se ne mijenja dok ne prihvate.',
    'they_lose_access_to_this_organization_and_everything_it_984eedd8' => 'Gube pristup ovoj organizaciji i svemu što ona dodjeljuje. Sam račun ostaje nepromijenjen.',
    'they_lose_every_role_and_application_this_organization_8c05da9e' => 'Odmah gube sve uloge i aplikacije koje im ova organizacija dodjeljuje.',
    'this_app_belongs_to_the_platform_and_is_available_to_ev_0c69cd5f' => 'Ova aplikacija pripada platformi i dostupna je svakoj organizaciji u ovom okruženju. Njome upravlja vaš operator.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Ova aplikacija ima opsege više API-ja: :part1 :part2. Token je namijenjen jednom API-ju odjednom, pa aplikacija željeni API navodi parametrom :part3. Zahtjev za opsege dvaju API-ja istodobno se odbija.',
    'this_changes_permissions_for_all_current_holders_of_thi_a515eb89' => 'Ovo mijenja dozvole svih trenutačnih nositelja ove uloge. Uloga se ne dodjeljuje novim osobama.',
    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'Ova instalacija nema Turnstile ključeve (CBOX_ID_TURNSTILE_SITE_KEY), pa nema provjere koju bi se moglo uključiti. Označena registracija umjesto toga potvrđuje adresu e-pošte.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Ova instalacija šalje SMS samo u ove države: :part1. Brojevi iz sljedećih država ne mogu primati kodove dok se te države ne uključe u CBOX_ID_SMS_ALLOWED_COUNTRIES: :part2.',
    'this_environment_s_own_issuer_what_an_sdk_discovers_fro_b00e706b' => 'Vlastiti izdavatelj ovog okruženja — s njega SDK dohvaća konfiguraciju i njega navodi polje :part1.',
    'this_is_the_app_s_only_live_secret_so_it_cannot_be_revo_d05986bb' => 'Ovo je jedina aktivna tajna aplikacije, pa se ne može opozvati zasebno — time bi aplikacija ostala bez načina prijave. Umjesto toga rotirajte je.',
    'this_member_a802a70b' => 'ovaj član',
    'this_organization_has_no_direct_role_or_membership_gran_1160edd2' => 'Ova organizacija nema izravnih dodjela uloga ili članstava za potvrdu.',
    'this_organization_owns_identity_providers_on_this_platf_f47c5479' => 'Ova organizacija posjeduje pružatelje identiteta na ovoj platformi. Najprije zatvorite njezine projekte u Organizacija › Projekti.',
    'this_organization_s_own_authentication_policy_is_droppe_a12f3b55' => 'Vlastita pravila autentifikacije ove organizacije uklanjaju se; od sada vrijede osnovna pravila okruženja.',
    'this_permission_is_removed_from_every_role_that_current_d88d6738' => 'Ova se dozvola uklanja iz svih uloga koje je trenutačno dodjeljuju. To se ne može poništiti.',
    'this_role_belongs_to_the_environment_and_applies_across_0a2b2ed6' => 'Ova uloga pripada okruženju i vrijedi u svim njegovim organizacijama. Ovdje vrijedi, ali je ne možete mijenjati.',
    'this_role_grants_no_permissions_the_application_that_de_59b043d0' => 'Ova uloga ne dodjeljuje dozvole. Aplikacija koja je deklarira određuje što smije raditi.',
    'this_role_is_declared_by_an_application_which_is_its_so_03e7843e' => 'Ovu ulogu deklarira aplikacija koja je mjerodavni izvor — ovdje se ne može uređivati.',
    'this_rule_binds_every_organization_here_choose_one_in_t_9d1bbde3' => 'Ovo pravilo obvezuje sve organizacije ovdje. Odaberite organizaciju u zaglavlju konzole da biste ga provjerili prema njezinim dodjelama.',
    'this_rule_binds_every_organization_in_the_environment_i_91928f48' => 'Ovo pravilo obvezuje sve organizacije u okruženju. Prikazano je jer ograničava vašu organizaciju; njime upravlja vaš operator.',
    'this_will_sign_people_out_of_part1_c2cac70c' => 'Ovo će odjaviti osobe iz :part1',
    'to_register_an_api_for_one_organization_find_it_here_it_48b04329' => 'Za registraciju API-ja jedne organizacije pronađite je ovdje — zatim će se iznad moći odabrati kao vlasnik.',
    'tokens_stop_being_issued_for_this_audience_this_cannot_7912313c' => 'Tokeni se prestaju izdavati za ovog primatelja. To se ne može poništiti.',
    'transfer_ownership_to_db1c7dbf' => 'Prenesi vlasništvo na',
    'try_a_different_search_roles_already_ticked_stay_in_thi_82c5a227' => 'Pokušajte drugu pretragu — već označene uloge ostaju na popisu bez obzira na upisano.',
    'turn_it_on_for_a_beta_organization_a_few_users_or_a_per_bea36395' => 'Uključite za beta organizaciju, nekoliko korisnika ili postotak svih korisnika.',
    'two_factor_authentication_part1_8c022f7b' => 'Dvofaktorska autentifikacija :part1',
    'type_the_organization_s_name_exactly_as_shown_to_confir_f021127d' => 'Za potvrdu upišite naziv organizacije točno kako je prikazan.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Ručno uneseni opsezi (:part1) nemaju vlasnika: prenose se neizmijenjeni i nikada nemaju registrirani API kao primatelja.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Dok API nije registriran, opseg je samo tekst u aplikaciji i svatko tko može uređivati aplikaciju može joj dodijeliti bilo koji opseg. Registrirajte API-je koje aplikacije pozivaju kako bi njihovi opsezi imali vlasnika.',
    'user_alice_dabd1db8' => 'user:alice',
    'ux_advanced_help' => 'Neobavezne postavke. Zadane vrijednosti odgovaraju većini aplikacija.',
    'ux_scopes_summary' => 'Odabrana dopuštenja: :count',
    'we_could_not_send_that_invitation_the_mail_server_refus_81a3f4df' => 'Nismo uspjeli poslati pozivnicu — poslužitelj e-pošte ju je odbio. Ništa nije stvoreno; pokušajte ponovno ili provjerite konfiguraciju e-pošte ove instalacije.',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Što se aplikaciji smije dopustiti na ovom API-ju. Te opsege mogu imati samo vlastite aplikacije vlasnika :part1.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Što se aplikaciji smije dopustiti na ovom API-ju. Vaše aplikacije mogu imati bilo koji opseg; aplikacija koju je registrirala organizacija samo one označene za organizacije.',
    'what_apps_ask_for_such_as_invoices_read_unique_in_this_2109e70c' => 'Što aplikacije traže, primjerice invoices:read. Jedinstveno u ovom okruženju.',
    'what_people_can_do_inside_your_apps_you_assign_roles_he_c31f1a20' => 'Što osobe mogu raditi u vašim aplikacijama. Ovdje dodjeljujete uloge; svaka aplikacija određuje što njezine uloge smiju raditi.',
    'what_this_role_is_allowed_to_do_tick_a_permission_to_gr_518298cc' => 'Što ova uloga smije raditi. Označite dozvolu da je dodijelite; uklonite oznaku da je opozovete.',
    'what_this_round_is_called_when_somebody_asks_which_revi_6e0713c0' => 'Naziv ovog ciklusa po kojem se prepoznaje iz kojeg je pregleda odluka proizašla, primjerice tromjesečje, revizija ili datum.',
    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Što vaš kod traži i što sadrži polje feature_flags u tokenu. Mala slova i znamenke, s - _ ili . između njih. Ne može se naknadno promijeniti.',
    'whatever_is_using_this_key_stops_working_immediately_th_8e55e6f5' => 'Sve što koristi ovaj ključ odmah prestaje raditi. To se ne može poništiti.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Sve s čime je korisnik povezao ovaj ključ odmah prestaje raditi. Ako možete, prvo ga obavijestite. To se ne može poništiti.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Kad netko stvori API ključ za jednu od vaših aplikacija, ovdje se prikazuje tko ga ima i što smije raditi.',
    'when_somebody_signs_out_or_an_administrator__3520d247' => 'Kada se netko odjavi ili administrator završi njegove sesije, ukloni ga ili deaktivira, Cbox ID šalje potpisani token za odjavu na ovu adresu, izravno između poslužitelja, kako bi i aplikacija mogla završiti vlastitu sesiju.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Odredište na koje Cbox ID šalje osobe nakon odjave iz ove aplikacije. URI koji aplikacija zatraži mora se točno podudarati s jednim od ovdje navedenih URI-ja, uključujući završnu kosu crtu. Inače Cbox ID ostavlja osobu na vlastitoj stranici nakon odjave. Ostavite prazno ako aplikacija ne preusmjerava osobe nakon odjave.',
    'where_this_app_publishes_the_roles_it_unders_e6047562' => 'Gdje ova aplikacija objavljuje uloge koje prepoznaje kako bi se ovdje mogle dodjeljivati.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Koje načine prijave :part1 nudi osim lozinke i koliko prijava traje. Jednaki su za sve organizacije u okruženju.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Tko pripada ovoj organizaciji i što smije raditi. Osoba koja ovdje još nema račun dobiva pozivnicu e-poštom.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Tko dobiva zastavicu kad ga nijedno pravilo ne navodi. Ostavite isključeno kako biste značajku prvo uveli navedenim organizacijama ili određenom postotku korisnika.',
    'whose_role_it_is_or_tick_the_box_above_to_define_it_for_970fb7fe' => 'Čija je uloga — ili označite gornji okvir da je definirate za sve organizacije.',
    'whose_roles_and_memberships_the_review_snapshots_e7576353' => 'Čije uloge i članstva pregled bilježi.',
    'whose_rule_it_is_or_tick_the_box_above_to_apply_it_to_e_82370728' => 'Čije je pravilo — ili označite gornji okvir da vrijedi za sve organizacije.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Bez uloga svatko tko se može prijaviti dobiva pristup koji aplikacija daje običnom korisniku. Ulogom jednom određujete tko su urednici, a tko podrška, i svaka povezana aplikacija poštuje tu dodjelu.',
    'work_through_the_list_certify_what_is_still_needed_revo_9bcc79ab' => 'Prođite kroz popis: potvrdite ono što je još potrebno, a opozovite ostalo.',
    'write_one_above_or_from_your_app_s_backend_in_batches_o_9ca507a7' => 'Zapišite jednu iznad ili ih šaljite iz pozadinskog sustava aplikacije u skupinama do 100.',
    'writes_531995e8' => 'zapisivanje',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Vi ste jedini vlasnik. Najprije prenesite vlasništvo na drugu osobu ili izbrišite organizaciju.',
    'you_can_also_part1_part2_part3_53f32513' => 'Druga mogućnost: :part1 :part2. :part3',
    'you_can_set_this_back_to_prefer_sso_or_both__b84203a4' => 'U svakom trenutku možete vratiti „Prednost SSO-u” ili „Oboje dostupno”; završene sesije ostaju završene.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'U svakom trenutku možete vratiti „Prednost SSO-u” ili „Oboje dostupno”; završene sesije ostaju završene.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Odmah gubite pristup. Kao vlasnik možete otići tek kad netko drugi postane vlasnik. Najprije prenesite vlasništvo ili izbrišite organizaciju u Postavkama.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Odmah gubite pristup ovoj organizaciji i njezinim aplikacijama. Administrator vas može ponovno pozvati.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Vlastiti model pristupa aplikacije: vrste resursa, odnosi za svaku vrstu i način nasljeđivanja. Aplikacija zapisuje torke, odnosno tko je povezan s čime, i provjerava pristup pri svakom zahtjevu.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Vaša pravila autentifikacije i dalje vrijede: jačina lozinke, provjera povreda podataka, potvrda e-pošte, ograničenja učestalosti i provjere botova.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Vaš vlastiti API. Za svaki opseg birate smiju li ga tražiti aplikacije koje registriraju organizacije.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'Vaša stranica prijave dobiva poveznicu „Stvori račun”, a aplikacije mogu slati osobe izravno na registraciju pomoću :part1.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Uloge i ovlasti u tokenu snimka su stanja u određenom trenutku. Prije svake zaštićene radnje zatražite aktualnu odluku o pristupu od Cbox ID-a i u aplikaciji provjerite pristup konkretnom resursu. Sam sadržaj tokena ne odražava naknadno oduzimanje pristupa:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Vaši načini prijave i aktivne sesije. Pristupni ključ najsigurnija je i najbrža opcija: uređaj ga otključava otiskom prsta ili prepoznavanjem lica, bez lozinke koju je moguće ukrasti phishingom.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Svaka radnja prihvaća se onako kako je aplikacija pošalje. Dodajte shemu radnji da bi se njezini događaji provjeravali pri primitku. Dosljednost dnevnika osigurava se pri zapisu događaja, a ne tek kada ga netko čita.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Svaki API ključ u konfiguraciji ili datoteci okruženja aplikacije ključ je koji ne možete centralno zamijeniti ni brzo oduzeti. Pohranjen ovdje, šifriran je, pristup se dodjeljuje po aplikaciji i može se opozvati jednim klikom.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Gumb se prestaje prikazivati, a vjerodajnice se brišu. Osobe koje su se prijavile putem tog pružatelja zadržavaju račune i mogu nastaviti koristiti lozinku. Da biste zadržali vjerodajnice, isključite pružatelja umjesto da ga izbrišete.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Obrnuti smjer: Cbox ID šalje vaše ljude u druge SaaS proizvode koje tvrtka koristi, putem njihovih SCIM krajnjih točaka. Jedno mjesto za dodjelu i ukidanje pristupa umjesto zasebne administratorske ploče svakog dobavljača.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Stvara organizaciju, njezina vlasnika, prvi proizvod i produkcijsko okruženje tog proizvoda. Vlasnik e-poštom dobiva poveznicu za postavljanje vlastite lozinke; ne birate je umjesto njega.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Trenutačno netko ovdje ručno dodaje i uklanja ljude. Povežite imenik koji vaša tvrtka već održava i obje će se radnje obavljati automatski, uključujući uklanjanja koja se najlakše zaborave.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Svi tokeni koje je izdao sada se opozivaju i više se ne može koristiti za novu prijavu. Aplikacija koja sama provjerava tokene prestaje ih prihvaćati kada isteknu, najkasnije do završetka same sesije.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Tijekom migracije s drugog sustava aplikacija može u svojem manifestu, uz uloge, navesti gdje se nalazi njezina stara prijava. Ovdje se prikazuje radi vašeg odobrenja prije nego što išta poduzme.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Napišite pravilo za dopuštanje, dodatnu provjeru ili blokiranje na temelju onoga što znate o korisnicima. Tražite dodatnu provjeru prijava iz zemalja u kojima ne poslujete ili izuzmite uredsku mrežu iz pravila učestalosti.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Potvrdom domene koju posjedujete, primjerice acme.com, Cbox ID može prepoznati vaše ljude prema adresi e-pošte i poslati ih izravno vašem pružatelju, bez odabira pravog gumba za prijavu.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Pružatelj identiteta koji uvozi metapodatke pružatelja usluge koristi ovaj URL umjesto zasebnog unosa ID-a entiteta i ACS URL-a. Radi i prije nego što je popunjena konfiguracija na strani pružatelja identiteta.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Ova se radnja ne može poništiti. Vjerodajnice, članstva i osobni podaci brišu se, a račun se pseudonimizira. Ako je osoba jedini vlasnik organizacije, prvo prenesite vlasništvo.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Djelujete kao ta osoba, u njezinoj sesiji i s njezinim pravima pristupa. Pristup je ograničen na 30 minuta i samo na čitanje ondje gdje konzola to može provesti. Svaki zahtjev bilježi se pod vašim imenom.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Suspenzija je jedina promjena koju ova stranica provodi i može se poništiti. Odabir i otvaranje okruženja mijenjaju samo prikaz konzole; ne mijenjaju ništa ni u jednom okruženju.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Trenutačno se ljudi prijavljuju vjerodajnicama pohranjenima ovdje. Povežite svojeg pružatelja kako bi koristili postojeći račun tvrtke i izgubili pristup ovdje čim ga tamo onemogućite.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Ne izdaje se nova tajna. Od sljedećeg pokušaja, uključujući ponovne pokušaje, isporuke sadržavaju zaglavlja druge sheme. Primatelj koji nije ažuriran odbijat će svaku od njih.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Pošaljite ovu jednokratnu poveznicu osobi koja upravlja njihovim pružateljem identiteta ako je nije primila e-poštom. Radi bez računa do isteka. Kopirajte je sada — prikazuje se samo jednom.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Softver u ovom okruženju koji čeka dopuštenje osobe. Agent čiji ključ zahtijeva odobrenje zaustavlja se i pita osobu koja je stvorila ključ. Odgovorite ovdje ili na telefonu.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Organizacija okuplja korisnike, načine prijave i uloge. Stvorite je iznad ili inicijalizirajte okruženje prvom organizacijom i administratorom na zaslonu Okruženja.',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Dodajte osobu u jednu od organizacija u nastavku kako biste joj dali pristup unutar nje. Ako aplikacije nemaju vlastito odvajanje organizacija, dodijelite joj ulogu administracije i podrške koja vrijedi u cijelom okruženju.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Uloga administracije i podrške dodjeljuje se vlastitom osoblju za cijelo okruženje. Vrijedi u svakoj organizaciji i administratori organizacija ne mogu je vidjeti ni promijeniti.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Zahtjevi se ovdje pojavljuju automatski kada aplikacija ili agent treba vaše odobrenje za djelovanje u vaše ime. Do tada ne trebate ništa učiniti. Ako se pojavi zahtjev koji niste pokrenuli, odbijte ga.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'SMS je najslabiji drugi faktor: osoba koja preuzme vaš telefonski broj prima vaše kodove. Prednost dajte aplikaciji za autentifikaciju ili pristupnom ključu, a SMS koristite samo ako te mogućnosti ne možete koristiti.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Zadani vizualni identitet okruženja: izgled hostirane stranice za prijavu, logotip i favicon te naziv i pošiljatelj koje korisnici vide. Svaka organizacija nasljeđuje te postavke ako ne postavi vlastite.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Detalji organizacije u ciljnom okruženju: članovi, SSO, domene, prava pristupa i nedavna aktivnost. Na ovoj stranici može se promijeniti samo status organizacije.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Sve organizacije u ovoj instalaciji. Otvorite jednu da biste pregledali njezine proizvode i okruženja. Suspenzija odjavljuje članove i zaustavlja autentifikaciju u svim okruženjima koja joj pripadaju.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Ove događaje šalje vaša aplikacija, jednim pozivom po skupini, pri čemu svaki događaj navodi organizaciju u kojoj se dogodio. Prikazuju se ovdje i administratorima te organizacije kako pristižu.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Dostupan je na svakoj stranici za prijavu u cijelom okruženju. Odaberite organizaciju da biste joj postavili vlastitog pružatelja, koji na njezinoj stranici zamjenjuje pružatelja okruženja.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code otvara preglednik za prijavu ovdje i pita što želite dopustiti. Nema ključa koji morate čuvati. Svaki MCP klijent koji se prijavljuje putem OAutha radi jednako s ovim URL-om.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Jedna organizacija u ovoj instalaciji: njezin tim, projekti i sva okruženja tih projekata. Suspenzija odjavljuje članove i zaustavlja autentifikaciju u svim tim okruženjima.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'Za cijelo okruženje: svatko s računom u ovom okruženju, iz bilo koje organizacije, može se prijaviti u ovu aplikaciju. Navedite organizaciju ako ne želite tako širok pristup.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Prijava putem servisa Entra ID, Okta ili Google Workspace dostupna je u paketu Enterprise. Obratite se timu koji vodi vaš račun kako biste je omogućili za ovu organizaciju.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Gdje ste prijavljeni, što može djelovati u vaše ime i što se dogodilo s vašim računom. Ako vidite nešto što ne prepoznajete, prekinite tu sesiju i promijenite lozinku.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Koliko se ljudi prijavilo i koliko su često aplikacije pozivale API u posljednjih 30 dana. Podaci služe za praćenje opterećenja i uočavanje anomalija; ovo nije račun.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Ovaj korisnik vlasnik je ili administrator organizacije, pa se ne možete prijaviti kao on. Ulazak u takav račun mogao bi dati trajnu kontrolu nad organizacijom osobi koja to učini.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'API ključevi koje aplikacije i agenti predstavljaju drugim servisima. Svaka je vrijednost šifrirana u pohrani, predaje se samo aplikacijama kojima odobrite pristup i nikad se više ne prikazuje nakon spremanja.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Aplikacije koje traže djelovanje u ime nekog od vaših korisnika. Svaki korisnik odobrava vlastite zahtjeve. Ovdje odbijte zahtjev samo ako izgleda kao zloupotreba; odbijanje se bilježi u revizijskom dnevniku.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Koliko često dohvaćati podatke i koja vlastita polja HR sustava kopirati za svaku osobu, primjerice mjesto troška ili lokaciju. Promjena polja uzrokuje potpuno sljedeće izvršavanje.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Poveznice dane IT administratoru ove organizacije koje još pružaju pristup. Opoziv poveznice odmah je onemogućuje; ono što je putem nje već postavljeno ostaje.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Zahtjevi agenata za djelovanje u ime korisnika pojavljuju se ovdje kako pristižu. Svaki korisnik odobrava vlastite zahtjeve; ova stranica služi za odbijanje onih koji izgledaju kao zloupotreba.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Kada su ispunjeni SVI uvjeti, Radar izvršava radnju ovog pravila i ne provjerava sljedeća pravila. Pravila se provjeravaju nakon popisa dopuštenih i blokiranih, a prije ugrađenih pravila.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Revizijski događaji koje aplikacija šalje o svim organizacijama koje opslužuje, od najnovijih. Događaji svake organizacije čine vlastiti lanac hash-vrijednosti.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Sve što je organizacija postavila i ono što još treba učiniti. Kontrolni popis postavljanja prati stvarno stanje: korak se automatski označava dovršenim čim je doista dovršen.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Kao administrator dodajte i aplikaciju za autentifikaciju ili pristupni ključ. Preuzimanjem telefonskog broja moguće je presresti SMS poruke, pa one ne mogu biti vaš jedini drugi faktor.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Brisanjem ove organizacije uklanjaju se svi njezini projekti i okruženja. Radi zaštite aktivnih pružatelja identiteta ova radnja nije dostupna za samostalno izvršavanje. Obratite se podršci za nastavak.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Odmah gubi pristup svim stranicama platforme u ovoj instalaciji, a postojeće sesije prestaju raditi pri sljedećem zahtjevu. Ovdje možete ponovno aktivirati korisnika.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Potvrđene domene usmjeravaju ljude na vašeg pružatelja identiteta, što je dio paketa Enterprise. Obratite se timu koji vodi vaš račun kako biste to omogućili za ovu organizaciju.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Dopuštenje je jedna radnja koju uloga smije izvršiti, primjerice stvaranje računa ili čitanje izvještaja. Ovdje možete definirati vlastita dopuštenja bez pisanja koda i zatim ih objediniti u uloge. Aplikacije mogu automatski registrirati svoja dopuštenja kako bi popis odgovarao pravilima koja stvarno provode. Dopuštenja koja stvorite pripadaju vama. Ona koja okruženje dijeli možete koristiti, ali ih ne možete mijenjati.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Pravila lozinki, zaključavanja, obaveznog drugog faktora i jedinstvene prijave koja vrijede pri svakoj prijavi. Za cijelo okruženje određuje se i dostupnost pristupnih ključeva i poveznica za prijavu te trajanje sesije. Okruženje postavlja osnovna pravila koja nasljeđuju sve organizacije. Organizacija može postrožiti pravila lozinki i drugog faktora, ali ih ne može ublažiti.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Radnje za koje agenti u ovom okruženju čekaju ljudsko odobrenje. Agent čiji ključ zahtijeva odobrenje radnje zaustavlja se i pita osobu koja je stvorila ključ. Ona može odgovoriti telefonom ili ovdje. Svaki administrator okruženja može odbiti sumnjiv zahtjev. Ispod su zahtjevi aplikacija za djelovanje u ime korisnika, koje svaki korisnik osobno odobrava.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Sesije i tokeni osobe opozivaju se. Brišu se njezini pristupni ključevi, drugi faktori, članstva, dodjele uloga, API tokeni, tajne u trezoru, uređaji i sve pohranjene kopije njezinih podataka. Od računa ostaje samo pseudonimiziran, onemogućen zapis. Aplikacije koje odavde sinkroniziraju osobe dobivaju obavijest da izbrišu tu osobu. Revizijski zapis zadržava neprozirni identifikator, bez imena ili adrese.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Sve što ste odobrili, uključujući uređaje ili alate naredbenog retka s kojih ste se prijavili.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Podaci koje vaši sustavi trebaju pohraniti za ovu organizaciju. Redci bez ključa izostavljaju se.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Procjenjuju se nakon vaših pravila. Svako aktivirano pravilo bilježi se; odlučuje najstrože.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'Isporuka se nastavlja. Zapisi nastali dok je bila isključena i dalje čekaju i poslat će se u sljedećoj seriji.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'Isporuka se odmah zaustavlja, a pohranjena vjerodajnica uništava se. Revizijski trag ostaje netaknut.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Sve veze između Cbox ID-a i drugih sustava na jednom mjestu: jedinstvena prijava, prijava društvenim računom, sinkronizacija direktorija i HR sustavi, izlazno upravljanje računima, SAML aplikacije, webhookovi, hookovi, tokovi zapisa i podatkovni kanali. Katalog pokreće postavljanje bilo koje vrste: svaka kartica otvara odgovarajuću stranicu. Popis veza prikazuje sve postojeće veze i njihovo stanje, s neispravnima na vrhu.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Svi načini prijave ovdje — lozinka, pristupni ključevi, poveznica za prijavu, društveni račun, jedinstvena prijava za tvrtke i drugi faktor — uz podatak jesu li uključeni i gdje se mijenjaju. Većinu određuje okruženje, a SSO veze pripadaju pojedinim organizacijama. Ako je način prijave isključen ili ograničen na razini instalacije, stranica to navodi zajedno s odgovarajućom postavkom.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Agent je svaki softver koji djeluje u ovom okruženju s upravljačkim ključem: AI asistent poput Claude Codea ili Cursora, interni bot ili vlastiti backend. Svakome dodijelite poseban ključ samo s potrebnim opsezima. Odredite koje radnje čekaju odobrenje i opozovite ključ čim agent završi ili nešto postane sumnjivo.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'API je vaša usluga koja prima pristupne tokene, primjerice https://api.example.com. Registrirajte je s opsezima koje prepoznaje kako biste ih mogli dodjeljivati. Određujete koje opsege smiju zatražiti aplikacije koje registriraju organizacije u ovom okruženju. Token namijenjen API-ju sadrži njegovu adresu kao ciljnu publiku koju vaša usluga provjerava.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Kako revizijski trag napušta Cbox ID: zakazani izvoz šalje nove zapise u SIEM ili arhivu svakih pet minuta. Dnevni zadatak zadržavanja stvara kontrolnu točku bez brisanja podataka. Ovdje možete preuzeti revizijsku povijest osobe za zahtjev za pristup prema GDPR-u ili u konzoli okruženja provjeriti rade li izvozi.',
    'exactly_as_shown_part1_stays_disabled_until_it_matches_fa10ae07' => 'Unesite točno kako je prikazano. Gumb „:part1” ostaje onemogućen dok se tekst ne podudara.',
    'my_part1_app_40bca4ad' => 'Moja aplikacija :part1',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Jedan dugotrajni proces, php artisan queue:autoscale, pokreće i zaustavlja radne procese koji obrađuju zadatke u redu čekanja.',
    'this_will_allow_part1_to_6ac64554' => 'Aplikacija :part1 moći će:',
