    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Izradite okruženje u odjeljku Platforma › Okruženja i njegovi će se brojevi prikazati ovdje.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'Sva okruženja u ovoj instalaciji i udio svakog u cjelini',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'Svi redovi pozadinskih zadataka u ovoj instalaciji i vrijeme čekanja najstarijeg zadatka u svakom od njih',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Svi brojači korištenja za ovo razdoblje i izvorni ključevi pripadajućih metrika',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Pronađite organizaciju ili korisnika u svim okruženjima, a ne samo u onom odabranom u konzoli.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Nijedna prijavljena domena ne odgovara pretrazi. Pokušajte s dijelom domene, bez @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Nijedna veza ne odgovara tom nazivu. Pokušajte s drugim pojmom za pretraživanje.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Nijedan imenik ne odgovara tom nazivu. Pokušajte s drugim pojmom za pretraživanje.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Nijedan URL krajnje točke ne odgovara pretrazi. Pokušajte s drugom pretragom.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Nijedan zapis ne odgovara tim filtrima. Pokušajte s općenitijim pojmom ili uklonite filtar.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Nijedan tok zapisnika ne odgovara tom nazivu. Pokušajte s drugom pretragom.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Nijedna izlazna veza ne odgovara tom nazivu. Pokušajte s drugom pretragom.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Svi elementi brenda koje korisnici vide na jednoj stranici: logotip, favicon, boje, font i zaobljenja stranice za prijavu koju hostamo, uz pregled uživo, te naziv proizvoda, pošiljatelj e-pošte i poruka dobrodošlice. Postavite ih jednom za cijelo okruženje kako bi ih naslijedile sve organizacije ili organizaciji dodijelite vlastiti izgled na kartici Vizualni identitet.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Svaki projekt u organizaciji ima vlastiti paket i dopušteni broj okruženja. Prikazani su uz potrošnju ovog mjeseca: organizacije, naplaćene veze jedinstvene prijave i prijave. Cijena uzima u obzir mjesečno aktivne korisnike i poslovne veze poput SSO-a i SCIM-a. U testnim okruženjima veze se ne naplaćuju.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Svi API ključevi koje su osobe u ovoj organizaciji stvorile za njezine aplikacije: vlasnik, aplikacija, dopuštene radnje i posljednja upotreba. Ključ smije samo ono što smije njegov vlasnik i prestaje raditi kada vlasnik napusti organizaciju. Opozovite ključeve koji su procurili ili se više ne koriste. Svaka osoba stvara vlastite ključeve u odjeljku Moj račun.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Tijekom prelaska s drugog sustava aplikacija može zatražiti provjeru e-pošte i lozinke osobe koja još nije u Cbox ID-u na staroj krajnjoj točki za prijavu. Testirajte je prije odobravanja. Prihvaćena osoba stvara se ovdje i više se ne šalje u stari sustav. Dok ta krajnja točka ne radi, osobe koje još nisu prenesene ne mogu se prijaviti.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Revizijski događaji koje aplikacija šalje za svaku organizaciju koju opslužuje: tko je što napravio u proizvodu i kada. Čuvaju se zasebno po organizaciji u lancu sažetaka i prikazuju njezinim administratorima. Koristite ih kada organizacija zatraži revizijski zapis svojeg računa. Definirajte sheme kako bi događaji imali dosljednu strukturu.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Nijedno buduće privremeno dopuštenje pristupa neće moći otvoriti ovu tajnu. Opoziv je trenutačan i trajan.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Nema aktivnih agenata. Opozvani i istekli ključevi ostaju na popisu radi evidencije.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Bez dopuštenja — samo identificira nositelja',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Ništa se ni za koga ne mijenja dok ovo ne uključite. Najprije testirajte prijavu.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Pohranjuje se samo sažetak. Ako izgubite ključ, opozovite ga i izradite novi.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Samo ovdje navedene aplikacije mogu dobiti privremeni pristup ovoj tajni. Svi ostali zahtjevi odbijaju se.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Vaše sesije na svim drugim uređajima prestat će raditi pri sljedećem zahtjevu. Na ovom uređaju ostajete prijavljeni.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'Ova organizacija još nema članova. Nitko se ne može prijaviti u nju dok netko ne bude pozvan ili dodan automatskom uspostavom računa.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Ovdje se ne postavlja lozinka. Korisnik prima poveznicu za prijavu e-poštom i bira način prijave.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Svaki se korak procjenjuje prema trenutačnom stanju, pa vodič uvijek prikazuje stvarno stanje ove organizacije.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Sada kopirajte ključ i predajte ga agentu. Čuva se samo sažetak, pa se ključ prikazuje samo ovaj put.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Domene e-pošte ove organizacije, svaka potvrđena DNS TXT zapisom. Nakon provjere domene možete uključiti obavezno usmjeravanje na SSO: svi s adresom na toj domeni koriste poslovnu SSO vezu umjesto lozinke. Provjerite sve domene na kojima korisnici imaju adrese prije nego što se oslonite na jedinstvenu prijavu.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Vlastiti model pristupa aplikacije: vrste resursa poput dokumenata i mapa, odnosi poput vlasnika, urednika i čitatelja te njihovo nasljeđivanje. Čitatelji mape, primjerice, mogu čitati svaki dokument u njoj. Aplikacija zapisuje odnose osoba i resursa te pri svakom zahtjevu pita smije li korisnik uređivati dokument. Shema određuje odgovor.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Ovo okruženje uz REST API pruža MCP poslužitelj, standardni način na koji AI asistenti pozivaju alate. Zalijepite adresu i upravljački ključ u Claude Code, Cursor ili drugi MCP klijent. Agent može raditi točno ono što dopuštaju opsezi ključa, uz iste provjere i revizijski zapis kao u konzoli.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Ključ omogućuje vašim skriptama i integracijama pozivanje API-ja aplikacije u vaše ime, bez prijave. Može samo ono što vi smijete u aplikaciji: ako se vaš pristup smanji, smanjuje se i pristup ključa. Ključ se prikazuje samo jednom. Kopirajte ga pri stvaranju i odmah ga opozovite ako procuri ili se više ne koristi.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Automatsko upravljanje računima zaustavlja se, a mapiranja grupa uklanjaju se. Stvoreni korisnici ostaju.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Automatsko upravljanje računima odmah se zaustavlja i sva se mapiranja grupa uklanjaju. Ova se radnja ne može poništiti.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'Automatsko upravljanje računima u odredišnoj aplikaciji odmah se zaustavlja. Ova se radnja ne može poništiti.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'Automatsko upravljanje računima u odredišnoj aplikaciji odmah se zaustavlja. Korisnici koji su ondje već stvoreni ostaju.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Telefonski broj uklonjen je. Ostali čimbenici autentifikacije i kodovi za oporavak korisnika ostaju nepromijenjeni.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'Već povezani korisnici zadržavaju opsege koje su odobrili dok se ponovno ne povežu.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Izvori su ažurirani. Promjena stupa na snagu pri sljedećem zahtjevu.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Drugi sustavi možda koriste ovu vrijednost. Njezina promjena mijenja URL-ove koje su pohranili.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Korisnici koji ovise o ovom pružatelju gube ovaj način prijave. Ova se radnja ne može poništiti.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Projekt je obustavljen. Njegova okruženja ostaju aktivna, ali nova se ne mogu dodavati dok se projekt ponovno ne aktivira.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Definicija uloge aktivirana je. Postojeći nositelji sada koriste ova dopuštenja.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Pravilo je aktivirano. Od sada se blokiraju dodjele pristupa koje bi ga prekršile.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Shema je spremljena. Od sada se događaji ove radnje provjeravaju prema njoj.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Shema je spremljena. Od sada određuje rezultat svake provjere.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Odbijajte događaje čija radnja nema shemu. Uključite kada svaka radnja koju aplikacija šalje ima shemu.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Objekti se zapisuju u prefix/yyyy/mm/dd/hh/batch.ndjson.gz, po jedan događaj u retku.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Samo za pohranu kompatibilnu sa S3, kao što su MinIO ili Cloudflare R2. Ako je prazno, koristi se AWS krajnja točka za regiju.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Registrirajte ovo kod pružatelja kao dopušteni URI za preusmjeravanje, točno kako je prikazano.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Webhookove, obavijesti o odjavi povezanim aplikacijama, ažuriranja uloga preuzeta iz tih aplikacija i e-poštu u redu obrađuju pozadinski procesi reda, bez čekanja korisnika. Ako nijedan proces ne radi, ništa se ne šalje, iako ostatak konzole izgleda ispravno. Na ovoj stranici možete uočiti problem.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Pregled u kojem provjeravate tko ima koju ulogu i potvrđujete treba li mu još. Pristup se neprimjetno gomila: ljudi mijenjaju timove, a zadržavaju stara dopuštenja. Pregled omogućuje njihovo uklanjanje. Opozivi se primjenjuju pri zatvaranju pregleda, a cijeli se postupak bilježi za revizora.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Ako aplikacija poslije navede drugi URL, ovo se odobrenje ukida i ponovno se traži. Promjena odredišta na koje se šalju lozinke zahtijeva novo odobrenje. Delegirana prijava je prijelazno rješenje: kada u starom sustavu ostane malo ljudi, isključite je i toj skupini pošaljite poruke za ponovno postavljanje lozinke.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Omogućuje prijavu postojećim poslovnim računom, primjerice Microsoft Entra ID, Okta ili Google Workspace, umjesto zasebnom lozinkom ovdje. Jednom povežite pružatelja identiteta i potvrdite domene e-pošte. Svi korisnici tih domena zatim se usmjeravaju pružatelju za prijavu.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Svaka osoba s identitetom u ovom okruženju, neovisno o organizacijama kojima pripada. Otvorite osobu za ponovno postavljanje lozinke ili drugog faktora, završavanje sesija, onemogućavanje računa, promjenu organizacija i uloga ili trajno brisanje prema zahtjevu za ostvarivanje prava na brisanje.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Zalijepite XML metapodataka pružatelja ili njihov URL i polja u nastavku automatski će se popuniti.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Zalijepite ovo kod svojeg pružatelja identiteta zajedno s bearer tokenom imenika koji povezujete.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Postavite ove adrese u svoj OIDC klijent. Automatsko otkrivanje izlaže sve krajnje točke.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Registrirajte aplikaciju koja koristi ovo okruženje kao pružatelja identiteta SAML.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Registrirajte aplikaciju kako bi se njezini korisnici mogli prijavljivati računima koje već imaju u ovom okruženju.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Samo ovdje navedene aplikacije dobivaju token. Svi ostali zahtjevi odbijaju se.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'Za ovu organizaciju nisu postavljena prava korištenja. Primjenjuju se zadane postavke instalacije.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'Organizacije u ciljanom okruženju, prikazane kao stablo upravljanja.',
    'owned_by_this_environment_rather_than_by_an_organizatio_60be3a32' => 'Pripada ovom okruženju, a ne organizaciji',
    'platform_operators_administer_environments_across_the_w_e0a9f173' => 'Operateri platforme upravljaju okruženjima u cijeloj instalaciji.',
    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Korištenje cijele platforme u svim okruženjima, a ne samo u onom odabranom u konzoli.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'Način na koji se vlasnici i operateri organizacija prijavljuju u Cbox ID postavlja se u konzoli okruženja platforme.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Ove se točke proširenja izvršavaju tijekom operacije, a ne nakon nje, i njihov odgovor mijenja ishod: vaša krajnja točka može dodati podatke tokenu ili odbiti prijavu. Izravno sudjeluju u izvršavanju operacije — sporu ili neispravnu krajnju točku osjetit će osoba koja se pokušava prijaviti.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Pružatelj identiteta ovdje sam stvara, ažurira i deaktivira osobe putem standarda SCIM. Dolazak ili odlazak evidentiran u kadrovskom sustavu stiže do aplikacija za nekoliko sekundi, bez zahtjeva podršci i zaostalih računa — što je posebno važno kada netko odlazi.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Broj organizacija, korisnika, veza za jedinstvenu prijavu, aplikacija i sinkronizacija korisnika u ovom okruženju, svaka s poveznicom na vlastitu stranicu. Prečaci u nastavku pokreću najčešće radnje: stvaranje organizacije, korisnika, veze za jedinstvenu prijavu ili aplikacije.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Uloga je odgovornost koju vaše aplikacije razumiju, primjerice „Urednik” ili „Djelatnik podrške”. Ovdje određujete tko ima koju ulogu, a svaka aplikacija sama određuje što njezine uloge dopuštaju. Uloge prate osobu u svim povezanim aplikacijama pa pristup dodjeljujete i oduzimate na jednom mjestu.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Kopira svaki zapis revizijskog dnevnika u alate sigurnosnog tima, poput sustava SIEM, čim se zapiše. Postavite odredište kako bi istrage započele u alatima koje tim već koristi, bez zahtjeva za izvozom. Dostava se obavlja barem jednom, pa su mogući povremeni duplikati.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Organizacija se pojavljuje ovdje čim se netko registrira. Možete je i sami izraditi opcijom Nova organizacija iznad.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Dodajte domenu adresa e-pošte ljudi u ovoj organizaciji, objavite TXT zapis i potvrdite domenu.',
    'prove_ownership_of_an_email_domain_to_route_your_team_t_bc84ec01' => 'Dokažite vlasništvo nad domenom e-pošte kako biste automatski usmjeravali tim na SSO.',
    'prove_the_organization_owns_a_domain_then_route_everyon_3c9f7db4' => 'Dokažite da organizacija posjeduje domenu, a zatim sve njezine korisnike usmjerite na prijavu organizacije.',
