    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Sheme metapodataka podskup su standarda JSON Schema: objekt čija su svojstva nizovi znakova, brojevi, cijeli brojevi, logičke vrijednosti ili null, s enumeracijama te ograničenjima duljine, raspona, uzorka i formata. Spremanje promjene stvara novu verziju; već zabilježeni događaji zadržavaju verziju prema kojoj su provjereni.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Svaka veza omogućuje osobama povezivanje vlastitog računa na servisu poput GitHuba, Googlea ili Slacka. Njihovi se tokeni ovdje pohranjuju šifrirani i redovito obnavljaju. Ovlaštene aplikacije traže valjan token pri svakom pozivu servisa u ime osobe, bez vlastite pohrane tokena.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Uloga za administraciju i podršku dodjeljuje se vlastitim zaposlenicima, primjerice timovima podrške ili operacija, za cijelo okruženje. Vrijedi u svakoj organizaciji, a administratori organizacija ne mogu je vidjeti, dodijeliti ni ukloniti. Vlastita uloga aplikacije dodijeljena na taj način vrijedi samo za tu aplikaciju.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Okruženje je potpuno izolirana usluga identiteta s vlastitim korisnicima, ključevima, prijavom i izdavateljem. Ovdje su navedena sva okruženja ove instalacije s organizacijom kojoj pripadaju. Stvorite okruženje, odaberite ga u konzoli i dodajte prvu organizaciju i administratora.',
