    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Telefon s instaliranom aplikacijom za autentifikaciju omogućuje odgovaranje na zahtjeve za odobrenje i obavještava vas kada se netko prijavi na vaš račun. Registrirajte ga jednom skeniranjem koda. Ako izgubite telefon, odmah ga ovdje uklonite kako više ne bi mogao ništa odobravati.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Organizacija je mjesto jedne registrirane tvrtke u ovoj instalaciji i sadrži njezine projekte, okruženja i tim. Otvorite je za pregled proizvoda i okruženja ili je obustavite: time se članovi odjavljuju i zaustavlja se prijavljivanje u svim njezinim okruženjima.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Kada aplikacija ili AI agent treba vaše odobrenje za djelovanje u vaše ime, ne može ga uvijek zatražiti na zaslonu pred vama — zato ga traži ovdje. Odobravajte samo zahtjeve koje ste sami pokrenuli i provjerite podudara li se prikazani kod s onim na uređaju koji je poslao zahtjev.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Projekt je jedan od vaših proizvoda, s vlastitim planom, prijavom i okruženjima poput produkcije i pretprodukcije. Ovdje otvorite okruženje kojim želite upravljati. Stvorite novi projekt kada pokrećete proizvod koji se treba zasebno naplaćivati i voditi.',
