    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Pronalazi organizaciju prema nazivu ili identifikatoru, odnosno korisnika prema imenu ili e-adresi, u svim okruženjima ove instalacije, a ne samo u onom odabranom u konzoli. Koristite kada netko traži pomoć, a ne znate u kojem se okruženju nalazi.',
