    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Samo za pružatelja koji ne objavljuje ključeve za potpisivanje (jwks_uri) u dokumentu za otkrivanje postavki. Inače se ključevi učitavaju odande, uključujući rotacije. Unesite javni ključ PEM. Pohranjuje se šifrirano i više se ne prikazuje; ostavite prazno da zadržite postojeći.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Određeni parovi uloga nikada ne smiju pripadati istoj osobi: onaj tko pokreće plaćanje ne bi ga smio i odobravati. Ovdje definirajte te parove. Cbox ID blokira nove dodjele koje bi prekršile pravilo i prikazuje tko već ima sukobljeni par uloga.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'API ključevi i tokeni koje aplikacije i agenti trebaju za druge usluge, pohranjeni ovdje šifrirano umjesto u konfiguraciji svake aplikacije. Tajnu vrijednost unosite jednom i određenim aplikacijama dopuštate njezinu upotrebu. Više se ne prikazuje; ako je izgubite, zamijenite je.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Poslužuje krajnje točke identiteta okruženja na vašoj domeni, primjerice login.example.com, umjesto na našoj. Vlasništvo domene dokazujete DNS TXT zapisom. Postavite je kada osobe tijekom prijave trebaju vidjeti samo vašu adresu.',
