    'usage_counters_fill_as_your_team_signs_in_invites_membe_a589d0b9' => 'Brojači korištenja popunjavaju se dok se tim prijavljuje, poziva članove i izdaje tokene.',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Svaka organizacija predstavlja tvrtku ili tim koji koristi vaš proizvod, s vlastitim članovima, ulogama, domenama i jedinstvenom prijavom. Stvorite jednu za svaku prijavljenu tvrtku. Otvorite je za upravljanje članovima, pozivnicama i potvrđenim domenama ili za obustavu.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID šalje potpisanu poruku vašoj krajnjoj točki nakon događaja, primjerice pridruživanja člana ili promjene uloge, kako bi sustavi mogli reagirati bez periodičkog provjeravanja. Neuspjela dostava ponovno se pokušava. Događaj se već zbio: krajnja točka prima obavijest, ali ne odlučuje o ishodu.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Shema određuje strukturu događaja neke radnje: koje vrste ciljeva navode i što sadrže njihovi metapodaci. Događaji radnje sa shemom provjeravaju se pri primitku. Bez sheme prihvaćaju se kako su poslani, osim ako je uključen strogi način rada.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Svi koji administriraju ovu organizaciju, njihove ugrađene uloge — Vlasnik, Administrator, Razvojni programer, Član ili Pregledavatelj — i okruženja kojima mogu pristupiti. Pozivajte osobe e-poštom i svakoj dajte samo okruženja potrebna za njezin posao.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Omogućite korisnicima aplikacija povezivanje vlastitih računa na GitHubu, Googleu, Slacku ili Salesforceu kako bi aplikacije mogle pozivati njihove API-je u ime korisnika. Tokeni se ovdje pohranjuju šifrirani i obnavljaju, a privremeno se daju samo ovlaštenim aplikacijama.',
    'the_invitee_accepts_by_email_nobody_is_added_to_an_orga_04408aaf' => 'Pozvana osoba prihvaća poziv e-poštom. Nitko se ne dodaje u organizaciju bez svojeg pristanka.',
    'this_user_has_no_signed_in_sessions_right_now_they_appe_0ac73d09' => 'Ovaj korisnik trenutačno nema prijavljenih sesija. Pojavit će se ovdje kada se prijavi.',
