    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Podaci korisnika izbrisani su. Račun je pseudonimiziran, a brisanje je zabilježeno kao user.erased u revizijskom zapisniku.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Operateri platforme administriraju sve organizacije i okruženja ove instalacije, iznad razine svake pojedine. Dodajte operatera samo osobi koja upravlja samom instalacijom i obustavite ga čim to prestane biti njezin posao.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Sve organizacije u okruženju odabranom u konzoli, prikazane kao stablo preprodavača, organizacija kojima upravljaju i njihovih podjedinica. Ovdje stvorite ili obustavite organizaciju ili je premjestite pod drugu nadređenu organizaciju.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Prijave, izdani tokeni, novi korisnici i registracije za dvofaktorsku autentifikaciju po danima tijekom posljednjih 30 dana, osim ako instalacija ne određuje drugo razdoblje. Stranica ostaje prazna dok operater instalacije ne konfigurira pohranu analitičkih podataka.',
