    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Svi preglednici i uređaji prijavljeni na vaš račun, aplikacije ovlaštene djelovati u vaše ime te nedavne prijave i sigurnosne promjene. Ako ne prepoznajete neku aktivnost, odjavite tu sesiju ili opozovite pristup aplikaciji, a zatim promijenite lozinku.',
