    'organization_created_but_the_owner_could_not_21800822' => 'Organizacija je stvorena, ali vlasniku nije bilo moguće poslati poveznicu. Zamolite ga da upotrijebi „Zaboravljena lozinka“.',
    'you_re_signed_in_you_don_t_belong_to_an_orga_67d0efb9' => 'Prijavljeni ste. Ovdje još ne pripadate nijednoj organizaciji — vaš račun i sigurnosne postavke pripadaju samo vama.',
    'when_an_app_or_agent_needs_your_go_ahead_to_act_as_you_3a85a2a9' => 'Kada aplikacija ili agent treba vaše odobrenje za djelovanje u vaše ime, traži ga ovdje. Odobravajte samo zahtjeve koje ste sami pokrenuli.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Trebate vjerodajnice vlastitog računa kod pružatelja, obično ID i tajnu klijenta. Apple umjesto tajne izdaje ključ za potpisivanje.',
    'you_stop_being_able_to_sign_in_with_it_if_it_66b928b9' => 'Više se nećete moći prijaviti ovom metodom. Ako vam je jedina, promjena se odbija. Najprije postavite lozinku ili dodajte pristupni ključ.',
    'you_will_no_longer_be_able_to_sign_in_with_a_a575bedf' => 'Više se nećete moći prijaviti SMS kodom. Aplikacija za autentifikaciju, pristupni ključevi i kodovi za oporavak ostaju nepromijenjeni.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'Vaša se krajnja točka poziva tijekom operacije i njezin odgovor mijenja ishod: može dodati podatke tokenu ili odbiti prijavu.',
    '_created_d8cbb77e' => ' · izrađeno: ',
    '_expires_886eec4c' => ' · istječe: ',
    'already_exists_here_4acf85c5' => 'ovdje već ima račun',
    'down_908aec45' => 'nedostupna',
    'including_yours_1124fe26' => 'uključujući vašu',
    'see_your_apps_83cc472a' => 'pogledajte svoje aplikacije',
    'the_full_quickstart_dd59dd4d' => 'cjeloviti vodič za brzi početak',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Upravljački ključ djeluje samo u vlastitom okruženju. Izvezite predložak ove aplikacije (GET /apps/{id}/blueprint) i registrirajte ga ključem drugog okruženja (POST /apps s `blueprint`).',
    'add_the_domain_and_publish_the_txt_record_it_shows_or_s_ddb14174' => 'Dodajte domenu i objavite prikazani TXT zapis — ili pošaljite IT administratoru organizacije poveznicu na administratorski portal da to učini.',
    'asked_before_every_rule_a_deny_entry_blocks_an_allow_en_e80b3f61' => 'Provjerava se prije svakog pravila. Zapis odbijanja blokira; zapis dopuštenja preskače sva pravila, uključujući ugrađena. Ako oba vrijede za isti pokušaj, odbijanje ima prednost.',
    'attach_this_to_the_iam_user_whose_access_key_the_stream_7659ba28' => 'Pridružite ovo IAM korisniku čiji pristupni ključ koristi tok: smije zapisivati objekte pod prefiksom i ništa drugo — bez čitanja, popisivanja ili brisanja.',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Odaberite SCIM ako vaš pružatelj šalje podatke nama, Google Workspace ili Entra ako ih trebamo povlačiti, ili svoj HR sustav — Workday, BambooHR, Rippling, HiBob ili Personio — kako bi se korisnici dodavali na datum početka rada.',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Od sljedećeg pokušaja blokade odbijaju prijave i registracije u ovom okruženju, a dodatne provjere traže potvrdu identiteta. Ako je pravilo pogrešno, stvarni korisnici bit će zaključani.',
    'give_it_the_endpoint_or_bucket_and_the_credential_it_ex_4cf81bb7' => 'Zadajte krajnju točku ili spremnik i očekivanu vjerodajnicu; za HTTP prijamnik ostavite tajnu praznom kako bi se generirao HMAC ključ.',
    'let_an_organization_sign_in_with_okta_entra_id_or_googl_cf114dfb' => 'Omogućite organizaciji prijavu putem Okte, Entra ID-a ili Google Workspacea — ili pošaljite administratoru poveznicu na administratorski portal da to sam postavi.',
    'selected_permissions_count' => 'Odabrana dopuštenja: :count',
    'sso_required_organization' => 'Poslovni SSO obvezan je za organizaciju :organization. Svi ostali načini prijave blokirani su dok se ovaj zahtjev ne promijeni u odjeljku „:policy”.',
    'sso_required_environment' => 'Poslovni SSO obvezan je za ovo okruženje. Svi ostali načini prijave blokirani su dok se ovaj zahtjev ne promijeni u odjeljku „:policy”.',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Prijava korisnika koji :part1 nikad se ne šalje starom sustavu. Vrijedi njegova lozinka u Cbox ID-ju, a stari sustav ne sudjeluje u autentifikaciji.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Ako je ta krajnja točka :part1, korisnici koji nisu migrirani ne mogu se prijaviti. Već migrirani korisnici nisu pogođeni.',
    'every_session_in_this_organization_ends_part1_part2_b33262fc' => 'Sve sesije u ovoj organizaciji završavaju — :part1 :part2.',
    'the_same_code_step_by_step_with_sign_out_part1_part2_4d2f071e' => 'Isti kod, korak po korak, s odjavom: :part1 :part2.',
    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'Najnoviji zapisi u revizijskom tragu organizacije :part1.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 odbija prijavu ako se vrijednost ne podudara potpuno. Rezervirana je za ovu konfiguraciju pa je sada možete zalijepiti u :part2, a ovdje spremiti kasnije.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — sesije, pristupni ključevi, drugi faktori, profili pružatelja identiteta, podaci direktorija, izdani tokeni, dodjele uloga i povijest revizije ostaju. Osobu možete ponovno aktivirati.',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => 'Preporučeni koraci: :part1, otprilike ovim redoslijedom. Svaki se automatski označi kad je doista dovršen; ništa ne treba ručno označavati.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Ovim se metodama ne prijavljuje u ovu konzolu. Administratori se prijavljuju putem Cbox ID-ja na :part2, njegovim metodama prijave.',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Upravljački ključ za jednog agenta. Može raditi samo ono što dopuštaju njegovi opsezi, a odabrane radnje čekaju vaše odobrenje na telefonu ili ovdje: :part1.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => ':part1 je pružatelj identiteta jednog proizvoda koji se naplaćuje prema vlastitom planu. Sadrži izolirana :part2 :part3, produkcijska i testna, svako s vlastitim korisnicima, ključevima i prijavom.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Ključ organizacije daje pristup samoj organizaciji — projektima, okruženjima, timu i ključevima — ne unutrašnjosti okruženja. Stvorite ga na najvišoj razini platforme pod :part1 :part2 :part3.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Aplikacije koje vjeruju ovom okruženju kao pružatelju SAML identiteta. Za prijavu postojećim računima kod drugih usluga koristite :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Odobrenja obuhvaćaju radnje upravljačkog API-ja. Ove opsege poslužuju krajnje točke koje još nisu radnje, pa se izvršavaju bez traženja odobrenja: :part1 :part2.',
    'link_an_app_with_the_same_owner_as_the_api_tokens_for_t_0a546071' => 'Povežite aplikaciju s istim vlasnikom kao API. Tokeni za ovaj API nose uloge i dopuštenja povezane aplikacije, pa ona mora pripadati istom vlasniku.',
    'not_configured_radar_can_still_block_but_cannot_ask_a_p_0a163809' => 'Nije konfigurirano — Radar i dalje može blokirati, ali ne može tražiti dokaz da je korisnik čovjek. Označena registracija umjesto toga potvrđuje adresu e-pošte.',
    'pick_where_the_trail_goes_splunk_elastic_graylog_cef_or_e69f3c8f' => 'Odaberite odredište revizijskog traga — Splunk, Elastic, Graylog, CEF ili bilo koji JSON prijamnik, Datadog ili vlastiti spremnik Amazon S3 ili Google Cloud Storage.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Dodaje ključeve zastavica značajki uključenih za osobu u organizaciji u koju se prijavila u pristupni token, ID token i UserInfo kao tvrdnju `feature_flags`.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Stavlja ULOGE osobe u ID token pod nazivom `groups` — to traže Kubernetes, Grafana, Vault i većina starijih SaaS aplikacija. U ovoj konzoli ne postoji pojam grupe: stvorite ulogu s nazivom koji aplikacija očekuje i pojavit će se ovdje.',
    'register_an_app_so_your_people_can_sign_in_to_it_with_t_9fcc62a6' => 'Registrirajte aplikaciju kako bi se vaši korisnici mogli prijaviti računom koji imaju ovdje. Ovaj korak pretvara Cbox ID u nešto što koriste.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Ova se ikona web-mjesta ne može koristiti. Pošaljite samu sliku kao base64 data: URI (data:image/png;base64,…). Udaljeni URL-ovi slika nisu prihvaćeni: sliku na stranici za prijavu dohvaća svaki posjetitelj, a vanjski URL otkrio bi njezinu poslužitelju tko su posjetitelji.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Ovaj se logotip ne može koristiti. Pošaljite samu sliku kao base64 data: URI (data:image/png;base64,…). Udaljeni URL-ovi slika nisu prihvaćeni: sliku na stranici za prijavu dohvaća svaki posjetitelj, a vanjski URL otkrio bi njezinu poslužitelju tko su posjetitelji.',
    'the_address_is_a_tor_exit_node_a_vpn_or_an_open_proxy_t_f7fc0d8a' => 'Adresa je izlazni čvor mreže Tor, VPN ili otvoreni proxy. Tor se prepoznaje iz lokalnog popisa izlaznih čvorova; VPN i proxy zahtijevaju uslugu analize IP adresa koja ih prijavljuje.',
    'the_button_disappears_from_every_sign_in_page_in_this_e_c817a046' => 'Gumb nestaje sa svake stranice za prijavu u ovom okruženju koja ga nasljeđuje. Vjerodajnice ostaju spremljene pa ga možete ponovno uključiti.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Gumb nestaje sa stranice za prijavu ove organizacije — gumb okruženja ne zamjenjuje ga. Vjerodajnice ostaju spremljene pa ga možete ponovno uključiti.',
    'the_console_is_pointed_at_this_environment_and_every_pa_4d2a0145' => 'Konzola se usmjerava na ovo okruženje i svaka stranica koju odsad otvorite čita njega umjesto trenutačnog. Ni u jednom se ništa ne mijenja.',
    'the_sign_in_page_your_people_see_is_yours_not_ours_logo_7573e3bf' => 'Stranica za prijavu koristi identitet vaše organizacije: logotip, boje i tekstove. Promjene se odmah vide u pretpregledu i primjenjuju na hostanu stranicu za prijavu ove organizacije.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Ova vjerodajnica zahtijeva odobrenje osobe za ovu radnju, ali nije zabilježena osoba koja bi ga dala. Pokrenite radnju iz konzole ili izdajte ključ iz konzole kako bi njegov vlasnik mogao odobriti.',
    'this_environment_falls_back_to_its_default_domain_every_201d6a2d' => 'Ovo se okruženje vraća na zadanu domenu. Svaki klijent vezan uz trenutačnog izdavatelja, URL za otkrivanje ili JWKS URL prestaje raditi dok se ne preusmjeri.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Trenutačno nismo mogli poslati e-poštu — ova instalacija ne može dosegnuti svoj poslužitelj e-pošte. Pokušajte kasnije; administrator može potvrditi vašu adresu i naredbom `php artisan cbox-id:users:confirm-email`.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Vaša stranica za prijavu nosi vaš logotip i boje. Ljudi u nju upisuju lozinku — treba izgledati kao vaša, ne naša.',
    'creating_an_app_issues_a_client_secret_shown_2840959a' => 'Stvaranje aplikacije izdaje tajnu klijenta koja se jednom prikazuje na sljedećem zaslonu — omogućuje prijavu kao ta aplikacija dok se ne rotira.',
    'registering_an_app_issues_a_client_secret_sh_631bb9f1' => 'Pri registraciji aplikacije stvara se tajna klijenta koja se prikazuje samo jednom, na sljedećem zaslonu. Omogućuje autentifikaciju u ime te aplikacije dok se ne zamijeni.',
    'there_is_no_other_environment_in_this_projec_bfd62f34' => 'U ovom projektu nema drugog okruženja kojim upravljate. Dodajte ga projektu ili zatražite pristup i pojavit će se ovdje.',
    'this_app_belongs_to_an_organization_and_an_o_5487ac51' => 'Ova aplikacija pripada organizaciji, a organizacija postoji samo u jednom okruženju. Preuzmite njezin predložak i registrirajte je u drugom okruženju pod organizacijom kojoj tamo pripada.',
    'this_app_registered_itself_so_it_is_not_one__ec7cea33' => 'Ova se aplikacija sama registrirala, pa nije jedna od vlastitih aplikacija ovog okruženja. Na isti se način može registrirati u drugom okruženju.',
    'this_app_signs_in_with_its_own_keys_and_each_a40a0c9b' => 'Ova se aplikacija prijavljuje vlastitim ključevima i svako okruženje treba imati svoje. Preuzmite njezin predložak i registrirajte je u drugom okruženju s njegovim skupom ključeva.',
    'app_keys_unavailable_organization_switch' => 'Aplikacija koja vas je poslala ovamo ne nudi API ključeve za organizaciju :organization. Pokušajte s drugom organizacijom ili se obratite podršci aplikacije.',
    'app_keys_unavailable_organization' => 'Aplikacija koja vas je poslala ovamo ne nudi API ključeve za organizaciju :organization. Obratite se podršci aplikacije.',
    'app_keys_unavailable_switch' => 'Aplikacija koja vas je poslala ovamo ne nudi API ključeve. Pokušajte s drugom organizacijom ili se obratite podršci aplikacije.',
    'app_keys_unavailable' => 'Aplikacija koja vas je poslala ovamo ne nudi API ključeve. Obratite se podršci aplikacije.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Povežite se jednom na najvišoj razini platforme, umjesto zasebno za svako okruženje. Agent prijavljen u vaše ime pristupa organizaciji, svim njezinim okruženjima kojima upravljate i vašem računu. Alat okruženja prima argument :part1 :part2, a REST API zaglavlje :part3, koji određuju gdje se djeluje. Agent može raditi ono što vi možete, unutar dopuštenih granica, a svaka kritična radnja čeka odobrenje na vašem uređaju.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Svaka organizacija osobi dodjeljuje jednu ulogu vrste :part1, koja određuje što smije administrirati, i proizvoljan broj uloga vrste :part2, koje određuju što smije u aplikacijama.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Okruženje „:part1” stvoreno je. U postavkama domena okruženja dodajte :part2 radi provjere putem DNS-a. Nepotvrđena domena ne može biti izdavatelj okruženja.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Okruženja pripadaju projektu, a projekt pripada organizaciji (:part1 :part2 :part3). Počnite ondje da vidite sve njezine resurse. Dvije vrste zapisa nikada nemaju organizaciju: :part4 je okruženje same instalacije, u kojem su operateri i osobe organizacija; okruženje označeno kao :part5 :part6 nema projekt, pa se ne naplaćuje i nijedna mu organizacija ne pristupa. Nijedno nije pogreška koju treba popravljati ovdje i ovaj zaslon ne mijenja njihovu pripadnost.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Svi načini prijave u :part1, njihovo stanje i mjesto promjene. Organizacije mogu postrožiti pravila: :part2 :part3.',
    'no_applications_match_part1_try_a_different_entity_id_386ed821' => 'Nijedna aplikacija ne odgovara pretraživanju „:part1”. Pokušajte s drugim ID-jem entiteta.',
    'no_organizations_match_part1_try_a_different_name_or_ha_72ccc404' => 'Nijedna organizacija ne odgovara pretraživanju „:part1”. Pokušajte s drugim nazivom ili identifikatorom.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Vaša krajnja točka ovim tajnim ključem provjerava zaglavlje :part1 svakog zahtjeva.',
    'ask_an_owner_of_the_organization_to_give_you_access_to__74d808e8' => 'Zatražite od vlasnika organizacije pristup okruženju :part1.',
    'hand_it_to_part1_over_a_channel_you_trust_we_never_stor_205e825e' => 'Predajte lozinku korisniku :part1 pouzdanim kanalom. Nikad je ne pohranjujemo u čitljivom obliku.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'Redoslijedom kojim ih osobe vide. Isključivanje pružatelja okruženja ovdje samo uklanja gumb s ove stranice; ne sprječava prijavu njime drugdje. Da bi vaš pružatelj bio jedini način prijave, zahtijevajte SSO pod :part1 :part2.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Pogođene osobe (:part1) više se ne mogu prijaviti u ovu organizaciju, a aplikacije koje se na nju oslanjaju prestaju ih autentificirati. Podorganizacije se ne obustavljaju. Organizaciju ovdje možete ponovno aktivirati.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Ključevi počinju ovim prefiksom kako bi ključ pronađen u zapisniku identificirao aplikaciju: :part1 :part2. Upotrijebite 2–16 malih slova ili znamenki, zatim :part3 ili :part4 :part5, jedinstveno u okruženju. Postavljanje omogućuje ključeve; brisanje zaustavlja nove, ali postojeći rade do opoziva.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Nitko u ovoj organizaciji nije stvorio ključ za njezine aplikacije. Osobe stvaraju vlastite pod Moj račun, za aplikaciju koja u Postavkama omogući API ključeve članova: :part1.',
    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Zalijepite cijelu JSON datoteku ključa servisnog računa kojem je na spremniku dodijeljena uloga roles/storage.objectCreator. Pohranjuje se šifrirano i više se ne prikazuje. :part1',
    'approved_part1_last_used_part2_part3_e3a21893' => 'Odobrenje: :part1 · Posljednja upotreba: :part2 :part3',
    'connected_part1_part2_part3_part4_a093c4a3' => 'Povezano: :part1 :part2 :part3 :part4',
    'add_this_dns_part1_record_at_your_domain_then_verify_it_3d494578' => 'Dodajte ovaj DNS zapis vrste :part1 svojoj domeni, a zatim pokrenite provjeru. Time dokazujete da upravljate domenom :part2.',
    'confirm_your_email_address_part1_to_make_changes_in_the_7b9d8809' => 'Potvrdite svoju adresu e-pošte :part1 kako biste mogli unositi promjene u konzoli.',
    'the_new_key_for_part1_copy_it_now_you_won_t_be_able_to_42e3ecb3' => 'Novi ključ za agenta :part1. Kopirajte ga sada jer ga više nećete moći vidjeti.',
    'bootstrap_part1_first_organization_admin_7459ca65' => 'Početno postavljanje okruženja :part1 — prva organizacija i administrator',
    'roles_held_across_the_whole_environment_in_every_organi_eb64cef7' => 'Uloge koje vrijede u cijelom okruženju, u svakoj organizaciji, čak i kada osoba ne pripada nijednoj. Organizacije nikada ne vide ove uloge. :part1 :part2',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Prijavite se u aplikaciju kao :part1 da vidite ono što vidi ta osoba. Aplikacija zna da ste to vi, a revizijski dnevnik organizacije bilježi tko, kada i zašto.',
